  return result;
}

const total = add(10, 20);

// 1. add() is called.
// 2. Execution context for add() is created.
// 3. Context is pushed onto the call stack.
// 4. a = 10, b = 20.
// 5. Function body executes.
// 6. Function returns 30.

function add(a, b) {
  return a + b;
}

console.log("Before");

const result = add(10, 20);

console.log(result);
console.log("After");

// Output:
// Before
