function infinite() {
  infinite();
}

infinite();

// Each call adds another execution context:
// infinite()
// infinite() → infinite()
// infinite() → infinite() → infinite()
// ...
// Eventually the call stack becomes full.
// Result: RangeError: Maximum call stack size exceeded

function countdown(number) {
  if (number === 0) {
    return;
  }

  console.log(number);
  countdown(number - 1);
}

countdown(3);

// Stack grows:
// countdown(3)
// countdown(3) → countdown(2)
// countdown(3) → countdown(2) → countdown(1)
// countdown(3) → countdown(2) → countdown(1) → countdown(0)
//
// countdown(0) returns, then previous calls return.

function first() {
  console.log("First");
}

function second() {
  console.log("Second");
}

first();
second();

console.log("Third");

// Output:
// First
// Second
// Third

// JavaScript executes the synchronous calls
// one at a time through the call stack.
